import gzip
import base64
import pickle
import sys
B64_DATA = """

""" 
try:
    fz = base64.b64decode(B64_DATA)
    picke = gzip.decompress(fz)
    blocks = pickle.loads(picke)
except Exception as e:
    print("Error decoding embedded data:", e, file=sys.stderr)
    sys.exit(1)
n, k = map(int, input().split())

key = (n, k)
if key in blocks:
    print(blocks[key])
else:
    print("No")